import{_ as e,o as i,c as t,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Operations Retrospective- Lessons from Scaling and Managing a Multi-PB Cluster - Mattias Skohg","description":"","frontmatter":{"title":"Ceph Operations Retrospective- Lessons from Scaling and Managing a Multi-PB Cluster - Mattias Skohg","date":"2025-01-23T00:00:00.000Z","updated":"2025-01-24T00:00:00.000Z","tags":["Ceph","Distributed Storage","Scale-Out Storage","Storage Management","High Availability"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Ceph_Operations_Retrospective_-_Lessons_from_Scaling_and_Managing_a_Multi-PB_Cluster_-_Mattias_Skohg.md","filePath":"posts/2025/Ceph_Operations_Retrospective_-_Lessons_from_Scaling_and_Managing_a_Multi-PB_Cluster_-_Mattias_Skohg.md","lastUpdated":1780459816000}'),r={name:"posts/2025/Ceph_Operations_Retrospective_-_Lessons_from_Scaling_and_Managing_a_Multi-PB_Cluster_-_Mattias_Skohg.md"};function o(s,a,n,_,h,u){return i(),t("div",null,[...a[0]||(a[0]=[l('<h3 id="改进后的中文总结内容" tabindex="-1">改进后的中文总结内容 <a class="header-anchor" href="#改进后的中文总结内容" aria-label="Permalink to &quot;改进后的中文总结内容&quot;">​</a></h3><p>Matias C，Engine Nordic 的 CTO，在斯德哥尔摩分享了他在一个 Ceph 集群项目中的经验，该项目从 4.5 PB 扩展到 8 PB，涵盖了硬件设计、集群设置、遇到的挑战以及扩展过程。</p><h4 id="项目背景" tabindex="-1">项目背景 <a class="header-anchor" href="#项目背景" aria-label="Permalink to &quot;项目背景&quot;">​</a></h4><ul><li>客户原本计划将硬件用于 vWar 和 IceWarp Gateway，但后来转向使用 CephFS 存储仪器数据、RGW 作为备份和迁移目标，并考虑用于 OpenShift CSI 连接。</li><li>使用了 10 台服务器，每台配备 28 块 HDD 和 2 块 SSD，没有 NVMe。</li></ul><h4 id="集群设置" tabindex="-1">集群设置 <a class="header-anchor" href="#集群设置" aria-label="Permalink to &quot;集群设置&quot;">​</a></h4><ul><li>使用了 Ceph Pacific 版本，300 个 OSD，总容量约 4.5 PB。</li><li>数据和元数据存储在 HDD 上，SSD 用于 RocksDB 的 BlueFS。</li><li>最初尝试了多 MDS 设置，但由于性能问题，最终回退到单 MDS。</li><li>使用子卷和子卷组设置文件系统。</li></ul><h4 id="遇到的挑战" tabindex="-1">遇到的挑战 <a class="header-anchor" href="#遇到的挑战" aria-label="Permalink to &quot;遇到的挑战&quot;">​</a></h4><ul><li>多 MDS 设置导致性能问题，回退到单 MDS。</li><li>缺乏备份，启用 CephFS 快照作为临时解决方案，但导致了后续的严重问题。</li><li>文件系统崩溃，需要通过删除损坏的文件和对象来恢复。</li></ul><h4 id="集群扩展" tabindex="-1">集群扩展 <a class="header-anchor" href="#集群扩展" aria-label="Permalink to &quot;集群扩展&quot;">​</a></h4><ul><li>从 4.5 PB 扩展到 8 PB，添加了新的节点。</li><li>PG 数量不足，导致数据分布不均，逐步增加 PG 数量以解决。</li><li>扩展过程需要几天到几个月。</li></ul><h4 id="经验教训" tabindex="-1">经验教训 <a class="header-anchor" href="#经验教训" aria-label="Permalink to &quot;经验教训&quot;">​</a></h4><ul><li>测试集群的重要性。</li><li>PG 数量调整的时机。</li><li>备份的必要性。</li><li>扩展计划的提前规划。</li></ul><h4 id="未来计划" tabindex="-1">未来计划 <a class="header-anchor" href="#未来计划" aria-label="Permalink to &quot;未来计划&quot;">​</a></h4><ul><li>在现有集群中创建 NVMe 元数据池。</li><li>考虑启动新的集群以避免旧集群的限制。</li></ul><p>Matias C 的分享强调了在大型 Ceph 集群中进行操作时需要注意的关键事项，包括硬件选择、集群设置、备份策略和扩展计划。他的经验教训对于其他 Ceph 用户和管理员来说是非常宝贵的。</p><h3 id="相关标签" tabindex="-1">相关标签 <a class="header-anchor" href="#相关标签" aria-label="Permalink to &quot;相关标签&quot;">​</a></h3><ul><li>Ceph</li><li>Distributed Storage</li><li>Scale-Out Storage</li><li>Storage Management</li><li>High Availability</li></ul>',17)])])}const p=e(r,[["render",o]]);export{c as __pageData,p as default};
